<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>                    <a href="{pigcms{:U('Merchant/type_index')}"  class="on">商家类型列表</a>|                    <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Merchant/add_merchant_type')}','添加商家类型',700,480,true,false,false,addbtn,'add',true);">添加商家类型</a>                </ul>			</div>						<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<style>					.table-list td{line-height:22px;padding-top:5px;padding-bottom:5px;}					</style>					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="100" align="center"/>						</colgroup>						<thead>							<tr>								<th>编号</th>                                <th>类型名称</th>                                <th>状态</th>                                <th>排序值</th>                                <th>添加时间</th>                                <th>开启/禁止</th>                                <th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="$merchant_type_list">								<volist name="merchant_type_list" id="vo">									<tr>										<td>{pigcms{$vo.type_id}</td>                                        <td>{pigcms{$vo.type_name}</td>                                        <td>                                            <if condition="$vo['type_status'] eq 0">                                                开启                                                <else/>                                                禁止                                            </if>                                        </td>                                        <td>{pigcms{$vo.sort}</td>                                        <td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>                                        <td>                                            <span class="cb-enable"><label class="cb-enable <if condition="$vo['type_status'] eq 0">selected</if>"><span onclick="discoverSwitch('{pigcms{$vo.type_id}', 0)" >开启</span><input type="radio" value="0" <if condition="$vo['type_status'] eq 0">checked="checked"</if> /></label></span>                                            <span class="cb-disable"><label class="cb-disable <if condition="$vo['type_status'] eq 1">selected</if>"><span onclick="discoverSwitch('{pigcms{$vo.type_id}', 1)">禁止</span><input type="radio" value="1" <if condition="$vo['type_status'] eq 1">checked="checked"</if> /></label></span>                                        </td>                                        <td class="textcenter">                                            <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Merchant/edit_merchant_type',array('type_id'=>$vo['type_id']))}','编辑商家类型信息',700,480,true,false,false,editbtn,'add',true);" >编辑</a>                                            | <a class="delete_row" parameter="type_id={pigcms{$vo.type_id}" url="{pigcms{:U('Merchant/del_merchant_type')}">删除</a>                                        </td>                                    </tr>								</volist>								<tr><td class="textcenter pagebar" colspan="11">{pigcms{$page}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="11">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>        <script>            var lockInfo = false;            function discoverSwitch(type_id, status) {                if (lockInfo) return;                lockInfo = true;                var url = "{pigcms{:U('Merchant/switch_merchant_type')}";                $.post(url,{'type_id':type_id,'type_status': status},function(data){                    console.log(data)                    if (data && (data.status === 1 || data.status === '1')) {                        location.reload();                    } else {                        alert(data.info)                    }                },'json');                setTimeout(function(){                    lockInfo = false;                },800);            }        </script><include file="Public:footer"/>